import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-10-18","description":"","frontmatter":{"title":"AI 动态 · 2026-10-18","date":"2026-10-18T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-18.md","filePath":"news/2026-10/ai-news-2026-10-18.md","lastUpdated":null}'),r={name:"news/2026-10/ai-news-2026-10-18.md"};function i(o,e,p,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-10-18" tabindex="-1">AI 动态 · 2026-10-18 <a class="header-anchor" href="#ai-动态-·-2026-10-18" aria-label="Permalink to &quot;AI 动态 · 2026-10-18&quot;">​</a></h1><blockquote><p>截至 2026-10-18。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="replit-将-openai-设为默认模型供应商-claude-仍可选用" tabindex="-1">Replit 将 OpenAI 设为默认模型供应商，Claude 仍可选用 <a class="header-anchor" href="#replit-将-openai-设为默认模型供应商-claude-仍可选用" aria-label="Permalink to &quot;Replit 将 OpenAI 设为默认模型供应商，Claude 仍可选用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-18">2026-10-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/1c0592a1597b.jpg" alt="配图"></p><p>Replit CEO Masad 澄清，OpenAI 已取代 Anthropic 成为平台默认模型供应商，Claude 仍向客户开放。对 AI 编程平台而言，默认模型切换直接影响成本结构与生成质量，也反映模型厂商在开发者入口上的争夺。对读者：若团队依赖 Replit 生成代码，建议重跑关键任务的基准并复核默认模型变更后的输出差异。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/17/replit-is-no-longer-working-with-anthropic-ceo-says/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="meta-删除引发爬虫与-ai-训练争议的条款表述" tabindex="-1">Meta 删除引发爬虫与 AI 训练争议的条款表述 <a class="header-anchor" href="#meta-删除引发爬虫与-ai-训练争议的条款表述" aria-label="Permalink to &quot;Meta 删除引发爬虫与 AI 训练争议的条款表述&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-18">2026-10-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/ee662d8995c9.webp" alt="配图"></p><p>Meta 更新商业条款，移除了此前引发抓取与 AI 训练担忧的措辞，发言人称爬虫方式并未改变。条款文本的微调往往先于监管与舆论压力出现，实际数据使用边界仍需看执行层面。对读者：内容站与 API 提供方应持续留存条款版本快照，把「文本未变」与「行为未变」分开评估。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/17/meta-removes-language-that-raised-scraping-and-ai-training-concerns/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-称员工结构趋于资深化-会议时间明显增加" tabindex="-1">Anthropic 称员工结构趋于资深化，会议时间明显增加 <a class="header-anchor" href="#anthropic-称员工结构趋于资深化-会议时间明显增加" aria-label="Permalink to &quot;Anthropic 称员工结构趋于资深化，会议时间明显增加&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-18">2026-10-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/763af1c8ae68.jpg" alt="配图"></p><p>Anthropic 披露过去一年员工构成与工作类型显著变化：初级岗位占比下降，员工投入会议的时间上升。这既是 AI 公司高速扩张后的组织成熟信号，也折射出自动化工具对初级工作的替代效应。对读者：关注 AI 团队招聘口径变化，评估自身岗位中可被工具压缩的环节并提前补足判断类能力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/17/anthropic-says-its-workforce-has-become-less-junior-and-is-spending-more-time-in-meetings/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="anthropic-设立公共福利基金-承诺捐出部分股份" tabindex="-1">Anthropic 设立公共福利基金，承诺捐出部分股份 <a class="header-anchor" href="#anthropic-设立公共福利基金-承诺捐出部分股份" aria-label="Permalink to &quot;Anthropic 设立公共福利基金，承诺捐出部分股份&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Anthropic News</span><time datetime="2026-10-18">2026-10-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/de99439f5793.jpg" alt="配图"></p><p>Anthropic 宣布将部分股份投入新设的 Anthropic Public Benefit Fund，首期承诺 5%，并随公司成长再追加 2%，尚待股东批准。该结构把公司估值增长与公共资金绑定，为 AI 公司治理提供新样本。对读者：跟踪该基金的治理与投向披露，可作为评估 AI 公司长期社会风险的一个观察指标。</p><p class="news-entry-source"><a href="https://www.anthropic.com/news/public-benefit-fund" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="deepseek-v4-1-flash-更新-能力提升且成本更低" tabindex="-1">DeepSeek V4.1 Flash 更新，能力提升且成本更低 <a class="header-anchor" href="#deepseek-v4-1-flash-更新-能力提升且成本更低" aria-label="Permalink to &quot;DeepSeek V4.1 Flash 更新，能力提升且成本更低&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">极客公园</span><time datetime="2026-10-18">2026-10-18</time></p><p>DeepSeek V4.1 Flash 升级至 V4.1-Flash-1017，网页、App 与 API 同步切换。官方称基准测试明显提升，同时任务运行时间与输出长度缩短，在多个 Harness 下达到新的性能-费用帕累托最优，并针对 CodeBuddy、WorkBuddy 等框架优化。对读者：高频调用场景可先小流量切到新版本，对比延迟与 token 消耗后再全量迁移。</p><p class="news-entry-source"><a href="http://www.geekpark.net/news/372512" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="微软披露-2-万亿参数-mai-base-2-模型" tabindex="-1">微软披露 2 万亿参数 MAI-Base-2 模型 <a class="header-anchor" href="#微软披露-2-万亿参数-mai-base-2-模型" aria-label="Permalink to &quot;微软披露 2 万亿参数 MAI-Base-2 模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">SiliconANGLE</span><time datetime="2026-10-17">2026-10-17</time></p><p>微软公布 MAI-Base-2，参数规模达 2 万亿，定位前沿基础模型。超大参数基座意味着训练与推理成本再上台阶，也预示微软自研模型与外部合作模型的分工将进一步明确。对读者：关注其后续是否开放 API 与定价，若仅内部使用，则短期对开发者选型影响有限，可先看评测数据再判断。</p><p class="news-entry-source"><a href="https://news.google.com/rss/articles/CBMipgFBVV95cUxOZ0FoZ05DRGg1cXY1SW96MncwcFZsbW8zVmhwc1lPU2VXa1BYejROSnZaeWdoUlBtRFB5Vjl1Nk1Pb2ZSbUtzdzU0MmlCcWszZzBTTUpsWVU5UjU5RmRTVFBoRVJjWWR3dDlhSFBCN2ZEeHhjLXJHa1FHVXhUTFpBdTFIY2tGb2FnLTNuM3ZZSWNLT3RoTTZkWmE3Z0x3MEllcUgyeFp3?oc=5" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="开源权重杀回榜首-meta-muse-spark-open-引发格局变化" tabindex="-1">开源权重杀回榜首：Meta Muse Spark Open 引发格局变化 <a class="header-anchor" href="#开源权重杀回榜首-meta-muse-spark-open-引发格局变化" aria-label="Permalink to &quot;开源权重杀回榜首：Meta Muse Spark Open 引发格局变化&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金人工智能</span><time datetime="2026-10-18">2026-10-18</time></p><p>Nathan Lambert 指出，美国开源权重模型竞争力出现质变，Meta 的 Muse Spark Open 成为最强美国本土开源模型，Reflection 首款 Beam 模型同期加入。Artificial Analysis 指数显示 Muse Wonder Full 得分 56。对读者：开源与闭源差距收窄时，可优先用开源权重做私有化与成本控制，同时保留闭源模型处理高难任务。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7697515895682875411" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="google-开源-harness2-测试时重写-agent-harness-的框架" tabindex="-1">Google 开源 Harness2：测试时重写 Agent Harness 的框架 <a class="header-anchor" href="#google-开源-harness2-测试时重写-agent-harness-的框架" aria-label="Permalink to &quot;Google 开源 Harness2：测试时重写 Agent Harness 的框架&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-18">2026-10-18</time></p><p>Google Research 发布 Apache-2.0 的 Harness2，可在测试时重写智能体的 harness。官方称仅一次细化步骤就让 GLM-5 在 WorkBuddy-Bench 上提升 11.5 分，且无需更新权重。对读者：若已在跑 Agent 评测，可把 harness 优化纳入调优清单，先复现该基准再判断是否值得接入生产。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/18/google-harness2-recursive-agent-harnessing-framework/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="pi-发布全新-agent-harness-并把-mcp-纳入核心" tabindex="-1">Pi 发布全新 Agent Harness，并把 MCP 纳入核心 <a class="header-anchor" href="#pi-发布全新-agent-harness-并把-mcp-纳入核心" aria-label="Permalink to &quot;Pi 发布全新 Agent Harness，并把 MCP 纳入核心&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-10-16">2026-10-16</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/1da25a765ce1.webp" alt="配图"></p><p>Pi 升级至 1.0，Code Mode 与原生 MCP 进入稳定版，同日推出新 Harness「Pi Durable」。曾公开拒绝 MCP 的 Pi 如今将其纳入核心，反映 MCP 已从争议协议走向事实标准。对读者：正在选型 Agent 框架的团队可对比 Pi Durable 的长时任务能力，并评估 MCP 生态工具的复用成本。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/hQOHf1ZXoBs7uMpWJQss?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="voxel51-3-0-发布-面向物理-ai-的多模态数据平台" tabindex="-1">Voxel51 3.0 发布：面向物理 AI 的多模态数据平台 <a class="header-anchor" href="#voxel51-3-0-发布-面向物理-ai-的多模态数据平台" aria-label="Permalink to &quot;Voxel51 3.0 发布：面向物理 AI 的多模态数据平台&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-18">2026-10-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/5d3b15c4742c.webp" alt="配图"></p><p>Voxel51 3.0 将多模态传感器数据的搜索、整理、标注与评估合并到一个平台，新增带 45+ MCP 工具的 Voxel51 Agent、数据集版本管理与免费自助版。对读者：做机器人或视觉数据管线的团队可先用免费层验证 MCP 工具链，再决定是否替换现有标注与评估流程。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/17/voxel51-3-0-physical-ai-data-platform/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="aspire-13-6-增加持久化仪表盘遥测-支持-java-与-rust-托管" tabindex="-1">Aspire 13.6 增加持久化仪表盘遥测，支持 Java 与 Rust 托管 <a class="header-anchor" href="#aspire-13-6-增加持久化仪表盘遥测-支持-java-与-rust-托管" aria-label="Permalink to &quot;Aspire 13.6 增加持久化仪表盘遥测，支持 Java 与 Rust 托管&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-10-18">2026-10-18</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/5bbfe6b22e19.webp" alt="配图"></p><p>微软发布 Aspire 13.6，仪表盘新增持久化遥测与运行历史，支持停靠式终端与数据库 REPL，并首次提供 Java 和 Rust 的第一方托管能力，另有两项预览版 Azure 集成。对读者：多语言微服务本地编排可评估 Aspire，重点验证遥测持久化对排查长链路问题的实际收益。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/4BUR4DmMxSBxyzYh6Fxz?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="用-document-currentscript-做内联渲染的小技巧" tabindex="-1">用 document.currentScript 做内联渲染的小技巧 <a class="header-anchor" href="#用-document-currentscript-做内联渲染的小技巧" aria-label="Permalink to &quot;用 document.currentScript 做内联渲染的小技巧&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Simon Willison</span><time datetime="2026-10-18">2026-10-18</time></p><p>Simon Willison 介绍 Lean Rada 的技巧：利用 document.currentScript 让内联 script 在页面加载时替换自身，例如直接输出当前年份；封装成快捷函数后即可得到一个极简模板语言。对读者：适合静态页与文档站的轻量动态内容，但需注意 CSP 限制与可维护性，不建议在复杂应用中替代正规渲染方案。</p><p class="news-entry-source"><a href="https://simonwillison.net/2026/Oct/17/document-currentscript/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="ai-流式传输工程指南-半截-json-如何边收边渲染" tabindex="-1">AI 流式传输工程指南：半截 JSON 如何边收边渲染 <a class="header-anchor" href="#ai-流式传输工程指南-半截-json-如何边收边渲染" aria-label="Permalink to &quot;AI 流式传输工程指南：半截 JSON 如何边收边渲染&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-10-18">2026-10-18</time></p><p>文章讨论模型直接返回结构化 JSON 时，前端如何在生成未完成时增量解析并渲染，覆盖商品卡片、流式表格等场景，并给出原生 JS、Vue 3 与 React 的可落地代码与性能对比。对读者：实现流式 JSON 渲染时应优先做容错解析与字段级占位，避免整段解析失败导致界面空白。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7697622920013021219" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
